package migratex

import (
	"context"
	"database/sql"
	"fmt"
	"net/url"
	"strings"
	"time"

	_ "github.com/go-sql-driver/mysql" // MySQL and MariaDB source driver
)

// mysqlSource reads from a MySQL or MariaDB database.
//
// The session is opened read-only through the DSN's transaction_read_only system
// variable, so no statement can modify the customer's database even if one were
// generated by mistake. That variable is the server-side equivalent of the
// PostgreSQL source's default_transaction_read_only and the SQLite source's
// query_only pragma: the enforcement is in the database, not in this code.
type mysqlSource struct {
	db *sql.DB
}

// NewMySQLSource opens a read-only MySQL or MariaDB connection.
//
// MariaDB and MySQL share the wire protocol, so the same adapter serves both; the
// driver reports which server answered and TestConnection records it.
func NewMySQLSource(ctx context.Context, cfg ConnectionConfig, password string) (Source, error) {
	if cfg.Host == "" {
		return nil, fmt.Errorf("host is required for a MySQL source")
	}
	if cfg.Database == "" {
		return nil, fmt.Errorf("database is required for a MySQL source")
	}
	port := cfg.Port
	if port == 0 {
		port = 3306
	}

	// transaction_read_only=1 is passed as a system variable, so the driver sets it
	// on every connection it opens rather than only on the first. parseTime keeps a
	// DATE/DATETIME/TIMESTAMP column a time.Time instead of a []byte, so it is
	// normalised to RFC3339 like the other sources. loc=UTC keeps that rendering
	// deterministic across a server in another time zone.
	params := url.Values{}
	params.Set("transaction_read_only", "1")
	params.Set("parseTime", "true")
	params.Set("loc", "UTC")
	params.Set("charset", "utf8mb4")
	params.Set("interpolateParams", "false")
	if cfg.SSLMode != "" && cfg.SSLMode != "disable" {
		params.Set("tls", "true")
	}
	dsn := fmt.Sprintf("%s:%s@tcp(%s:%d)/%s?%s",
		cfg.Username, password, cfg.Host, port, cfg.Database, params.Encode())

	db, err := sql.Open("mysql", dsn)
	if err != nil {
		return nil, fmt.Errorf("open MySQL source: %w", err)
	}
	db.SetMaxOpenConns(2)
	db.SetConnMaxLifetime(time.Minute)
	if err := db.PingContext(ctx); err != nil {
		db.Close()
		return nil, fmt.Errorf("connect to MySQL source: %w", err)
	}
	return &mysqlSource{db: db}, nil
}

func (s *mysqlSource) Kind() SourceKind { return SourceMySQL }

// TestConnection confirms the server is reachable and that the session really is
// read-only. It reads the variable back rather than trusting the DSN, because a
// server that ignores the parameter would otherwise be treated as safe.
func (s *mysqlSource) TestConnection(ctx context.Context) error {
	var version string
	if err := s.db.QueryRowContext(ctx, "SELECT VERSION()").Scan(&version); err != nil {
		return fmt.Errorf("MySQL connection test failed: %w", err)
	}
	var readOnly int
	if err := s.db.QueryRowContext(ctx, "SELECT @@transaction_read_only").Scan(&readOnly); err != nil {
		return fmt.Errorf("could not read transaction_read_only: %w", err)
	}
	if readOnly != 1 {
		return fmt.Errorf("the MySQL session is not read-only; refusing to continue")
	}
	return nil
}

// DiscoverSchema lists the base tables in the configured database and their
// columns. information_schema is used rather than SHOW statements so the result is
// a normal result set that can be scanned column by column.
func (s *mysqlSource) DiscoverSchema(ctx context.Context) ([]TableSchema, error) {
	const q = `
		SELECT c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.IS_NULLABLE,
		       CASE WHEN c.COLUMN_KEY = 'PRI' THEN 1 ELSE 0 END AS is_primary
		FROM information_schema.COLUMNS c
		JOIN information_schema.TABLES t
		  ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
		WHERE c.TABLE_SCHEMA = DATABASE() AND t.TABLE_TYPE = 'BASE TABLE'
		ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION`
	rows, err := s.db.QueryContext(ctx, q)
	if err != nil {
		return nil, fmt.Errorf("discover schema: %w", err)
	}
	defer rows.Close()

	byName := map[string]*TableSchema{}
	var order []string
	for rows.Next() {
		var table, column, dataType, nullable string
		var primary int
		if err := rows.Scan(&table, &column, &dataType, &nullable, &primary); err != nil {
			return nil, err
		}
		t, ok := byName[table]
		if !ok {
			t = &TableSchema{Name: table}
			byName[table] = t
			order = append(order, table)
		}
		t.Columns = append(t.Columns, ColumnInfo{
			Name: column, Type: dataType, Nullable: nullable == "YES", PrimaryKey: primary == 1,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := make([]TableSchema, 0, len(order))
	for _, name := range order {
		out = append(out, *byName[name])
	}
	return out, nil
}

func (s *mysqlSource) CountRows(ctx context.Context, table string) (int64, error) {
	quoted, err := mysqlQuoteIdentifier(table)
	if err != nil {
		return 0, err
	}
	var n int64
	if err := s.db.QueryRowContext(ctx, "SELECT count(*) FROM "+quoted).Scan(&n); err != nil {
		return 0, fmt.Errorf("count rows in %s: %w", table, err)
	}
	return n, nil
}

func (s *mysqlSource) ReadBatch(ctx context.Context, table string, columns []string,
	watermark map[string]any, limit int) ([]map[string]any, error) {

	quotedTable, err := mysqlQuoteIdentifier(table)
	if err != nil {
		return nil, err
	}
	if len(columns) == 0 {
		return nil, fmt.Errorf("at least one column is required")
	}
	quotedCols := make([]string, 0, len(columns))
	for _, c := range columns {
		q, err := mysqlQuoteIdentifier(c)
		if err != nil {
			return nil, err
		}
		quotedCols = append(quotedCols, q)
	}
	if limit <= 0 || limit > 100000 {
		limit = 1000
	}
	orderBy := ""
	if col, ok := watermark["column"].(string); ok && col != "" {
		q, err := mysqlQuoteIdentifier(col)
		if err != nil {
			return nil, err
		}
		orderBy = " ORDER BY " + q + " ASC"
	}

	q := fmt.Sprintf("SELECT %s FROM %s%s LIMIT ?", strings.Join(quotedCols, ", "), quotedTable, orderBy)
	rows, err := s.db.QueryContext(ctx, q, limit)
	if err != nil {
		return nil, fmt.Errorf("read from %s: %w", table, err)
	}
	defer rows.Close()

	colNames, err := rows.Columns()
	if err != nil {
		return nil, err
	}
	var out []map[string]any
	for rows.Next() {
		values := make([]any, len(colNames))
		ptrs := make([]any, len(colNames))
		for i := range values {
			ptrs[i] = &values[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return nil, err
		}
		rec := make(map[string]any, len(colNames))
		for i, name := range colNames {
			rec[name] = normaliseValue(values[i])
		}
		out = append(out, rec)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if since, ok := watermark["value"]; ok && since != nil && len(out) > 0 {
		col, _ := watermark["column"].(string)
		out = filterAfter(out, col, since)
	}
	return out, nil
}

func (s *mysqlSource) Close() error { return s.db.Close() }

// mysqlQuoteIdentifier validates and backtick-quotes an identifier.
//
// MySQL quotes identifiers with backticks by default; the double quote the other
// sources use only works when ANSI_QUOTES is enabled, which a customer's server
// is not required to set. A backtick cannot appear in an identifier this function
// accepts, so quoting it cannot escape into a second identifier.
func mysqlQuoteIdentifier(name string) (string, error) {
	if name == "" {
		return "", fmt.Errorf("empty identifier")
	}
	// MySQL caps identifiers at 64 characters; reject longer rather than truncate.
	if len(name) > 64 {
		return "", fmt.Errorf("identifier %q is too long", name)
	}
	for _, r := range name {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == '_' || r == '$' {
			continue
		}
		return "", fmt.Errorf("identifier %q contains an unsupported character", name)
	}
	return "`" + name + "`", nil
}
